import '../models/auth/terminal_linking.dart';
import '../models/user.dart';

abstract class AuthRepository {
  bool get isPendingSync;
  DateTime? get lastSyncTimestamp;
  String? get lastAuthError;

  Future<User?> loginOnline(String email, String password, {String? tenantSlug});

  /// Claims a pre-auth terminal linking code (issue #556): exchanges the
  /// 6-char code generated by the owner dashboard for the tenant binding
  /// (slug) BEFORE any login attempt. Must be called with NO Authorization
  /// header. Throws [LinkingClaimException] with a user-facing message on
  /// failure (401 generic, 429 rate-limited, network errors).
  Future<TerminalLinking> claimLinkingCode(String code, String deviceId);
  Future<void> syncStaff();
  Future<User?> loginOffline(String userId, String pin);
  Future<bool> authorizeOverride({required String supervisorId, String? pin, String? totpCode});
  Future<User?> getCurrentUser();
  Future<String?> getAccessToken();
  Future<void> logout();

  // User Management
  Future<List<User>> getAllUsers();
  Future<void> saveUser(User user, {String? pin});
  Future<void> deleteUser(String userId);
}
